#include "MixAnalysis.h"
static void testMixAnalysis(const File& root,Assets& assets){
    for(double hz:{93.75,750.,8000.})for(int sign:{-1,1}){
        auto meter=std::make_unique<MixMeter>();bool finite=true;for(int i=0;i<49152;++i){auto v=(float)(.25*std::sin(2*MathConstants<double>::pi*hz*i/48000));finite&=meter->feed(v,(float)(sign*v));}
        auto m=meter->finish();expect(finite,"finite calibrated stereo measurement");expect(m.frames==49152&&std::abs(m.peak[0]-(hz==8000?.25*std::sqrt(3.)/2:.25))<.001&&std::abs(m.rms[0]-.25/std::sqrt(2.))<.0001,"calibrated sample peak and RMS agree with sine amplitude");expect(std::abs(m.dc[0])<.0001&&m.fullScale[0]==0&&m.correlationValid&&std::abs(m.correlation-sign)<1e-9,"DC, full-scale counts and positive/negative stereo correlation calibrated");expect(m.bandFraction[hz<200?0:hz<4000?1:2]>.995,"stereo FFT energy is assigned to its measured frequency band");
    }
    auto dc=std::make_unique<MixMeter>();for(int i=0;i<4096;++i)dc->feed(1.25f,-.5f);auto d=dc->finish();expect(d.peak[0]==1.25&&d.rms[0]==1.25&&d.dc[1]==-.5&&d.fullScale[0]==4096&&!d.correlationValid,"constant offset preserves DC and clipping counts without inventing correlation");expect(d.bandFraction==std::array<double,3>{},"FFT power balance removes DC before its Hann window");
    for(float value:{.01f,.03f,.3f,.7f}){auto constant=std::make_unique<MixMeter>();for(int i=0;i<48000;++i)constant->feed(value,value);auto measured=constant->finish();expect(!measured.correlationValid&&measured.correlation==0&&measured.dc[0]==value,"non-binary DC constants cannot invent correlation through cancellation error");}
    auto extreme=std::make_unique<MixMeter>();for(int i=0;i<4096;++i){float value=(float)(1e35*std::sin(2*MathConstants<double>::pi*750*i/48000));extreme->feed(value,-value);}auto high=extreme->finish();expect(high.correlationValid&&high.correlation<-.999999&&high.bandFraction[1]>.99&&std::isfinite(high.rms[0]),"FFT scaling and centered covariance stay finite for large finite float audio");
    auto one=std::make_unique<MixMeter>();for(int i=0;i<1027;++i)one->feed((float)std::sin(i*.1),0);auto m=one->finish();expect(m.frames==1027&&!m.correlationValid&&m.rms[1]==0,"partial FFT blocks and one-sided output are measured safely");auto silent=std::make_unique<MixMeter>();for(int i=0;i<400;++i)silent->feed(0,0);m=silent->finish();expect(!m.correlationValid&&m.bandFraction==std::array<double,3>{}&&m.rms[0]==0,"silence has finite levels and unavailable correlation");expect(!silent->feed(std::numeric_limits<float>::infinity(),0)&&!silent->feed(0,std::numeric_limits<float>::quiet_NaN()),"non-finite samples reject before accumulating metrics");
    auto p=emptyProject();p.bpm=120;p.master=.8f;p.masterSoftClip=false;p.loop=true;p.metronome=true;p.songMode=false;p.patterns[0].length=4;auto& track=p.tracks[7];track.volume=1.5f;track.send=0;track.drive=0;track.cutoff=20000;track.instrument=Instrument::lead;for(int i=0;i<32;++i)p.patterns[0].lanes[7].push_back({0,2,60,1});auto original=JSON::toString(projectToJson(p));MixAnalysisReport report;auto valid=analyzeMix(p,root,report);if(valid.failed())std::cerr<<valid.getErrorMessage()<<'\n';expect(valid.wasOk(),"actual offline mix analysis succeeds");if(valid.failed())return;
    expect(JSON::toString(projectToJson(p))==original&&report.measured.frames==192000,"analysis preserves source and measures exactly four beats plus a two-second tail");expect(report.canReduce&&report.masterAfter<report.masterBefore&&report.reductionDb>0&&report.measured.peak[0]>1,"summed loud voices produce a reviewable Master reduction");
    auto withoutClick=p;withoutClick.loop=false;withoutClick.metronome=false;RenderSettings settings;settings.bits=32;auto wav=root.getChildFile("mix-analysis-float.wav");expect(renderAudio(withoutClick,assets,root,wav,settings).wasOk(),"measurement comparison uses actual float WAV export");AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(fm.createReaderFor(wav));expect(reader&&reader->usesFloatingPointData,"mix comparison export retains peaks above full scale");if(reader){AudioBuffer<float> buffer(2,(int)reader->lengthInSamples);reader->read(&buffer,0,buffer.getNumSamples(),0,true,true);auto reference=std::make_unique<MixMeter>();for(int i=0;i<buffer.getNumSamples();++i)reference->feed(buffer.getSample(0,i),buffer.getSample(1,i));auto expected=reference->finish();expect(expected.frames==report.measured.frames&&expected.peak==report.measured.peak&&expected.rms==report.measured.rms&&expected.bandFraction==report.measured.bandFraction,"offline report exactly matches independently decoded export samples including tails");}
    auto corrected=p;corrected.master=(float)report.masterAfter;MixAnalysisReport verified;expect(analyzeMix(corrected,root,verified).wasOk()&&jmax(verified.measured.peak[0],verified.measured.peak[1])<=std::pow(10.,-1./20)+1e-5&&!verified.canReduce,"proposed Master gain renders at the stated ceiling and needs no second reduction");
    auto saturated=p;saturated.masterSoftClip=true;expect(analyzeMix(saturated,root,verified).wasOk()&&!verified.canReduce&&verified.levelReason.contains("saturation"),"saturated Master requires manual review instead of an invalid linear correction");auto automated=p;Clip c;c.automationTarget=5;c.beat=0;c.length=4;c.points={{0,1},{4,1}};automated.clips.push_back(c);expect(analyzeMix(automated,root,verified).wasOk()&&!verified.canReduce&&verified.levelReason.contains("automation"),"Master automation blocks base-fader correction even in PAT mode");
    std::atomic<bool> cancel{true};verified.title="Sentinel";expect(analyzeMix(p,root,verified,&cancel).failed()&&verified.title=="Sentinel","cancelled analysis cannot replace the caller's prior report");auto longSong=p;longSong.songMode=true;longSong.clips={{7,0,0,600},{7,0,700,600}};auto tooLong=analyzeMix(longSong,root,verified);expect(tooLong.failed()&&tooLong.getErrorMessage().contains("ten minutes")&&verified.title=="Sentinel","ten-minute snapshot limit rejects before rendering and retains prior output");
    auto missing=p;missing.tracks[0].samplePath=root.getChildFile("absent-mix.wav").getFullPathName();missing.tracks[0].instrument=Instrument::sample;expect(analyzeMix(missing,root,verified).failed(),"unresolved source audio cannot produce a misleading analysis");
    AssetFingerprints first{{"a","hash",10,1,0}},second=first;second[0].modified=4;expect(sameMixAssets(first,second),"unchanged source bytes remain valid after timestamp-only changes");second[0].hash="other";expect(!sameMixAssets(first,second),"same-size source byte changes invalidate the correction");expect(mixProjectHash(p,root)!=mixProjectHash(corrected,root),"source hash includes the complete project gain state");
    auto sampled=p;sampled.tracks[7].instrument=Instrument::sample;sampled.tracks[7].samplePath=wav.getFullPathName();sampled.patterns[0].lanes[7]={{0,2,60,1}};MixAnalysisReport fromFile;
    expect(analyzeMix(sampled,root,fromFile).wasOk()&&fromFile.assets.size()==1&&fromFile.assets[0].hash==SHA256(wav).toHexString(),"offline analysis fingerprints the actual decoded sample source before and after rendering");
    auto changedBytes=root.getChildFile("mix-analysis-source-copy.wav");expect(wav.copyFileTo(changedBytes),"copy sample source for same-size identity verification");AssetFingerprint a,b;expect(fingerprintAssetFile(changedBytes,a).wasOk(),"source identity is measured from real audio bytes");{FileOutputStream stream(changedBytes);stream.setPosition(changedBytes.getSize()-8);stream.writeInt(1234567);}expect(fingerprintAssetFile(changedBytes,b).wasOk()&&a.bytes==b.bytes&&a.hash!=b.hash&&!sameMixAssets({a},{b}),"same-size real audio changes invalidate original source identity");
    auto file=root.getChildFile("mix-analysis-report.json");expect(saveMixAnalysisReport(file,report).wasOk()&&(int)JSON::parse(file)["schema"]==1&&JSON::parse(file)["summary"].toString().contains("not LUFS"),"saved report includes versioned machine measurements and explicit human units");auto previous=file.loadFileAsString();auto invalid=report;invalid.measured.rms[0]=std::numeric_limits<double>::quiet_NaN();expect(saveMixAnalysisReport(file,invalid).failed()&&file.loadFileAsString()==previous,"invalid report cannot replace the previous persisted analysis");
}
